import json
import os
from json import JSONDecodeError

from ..utils.logger import logger


def get_json_env_variable_value(env_variable, default_object=""):
    """
    Get JSON environmental variable from OS or from the context JSON file.

    If none of the above exist - return default_object.

    :param env_variable: Environment variable name
    :param default_object: Default object which should be returned if env_variable doesn't exist
    """
    value = os.getenv(env_variable)
    if value is None and (context_path := os.getenv("CM_CONTEXT_FILEPATH")) is not None:
        with open(context_path, "r", encoding="utf-8") as context_file:
            context_data = json.load(context_file)
            context = context_data["context"]["values"]
            item = context.get(env_variable, {})
            return item.get("value", default_object)
    else:
        try:
            return json.loads(value)
        except TypeError:
            logger.debug(f"Variable {env_variable} not found in the OS")
            return default_object
        except JSONDecodeError:
            logger.debug(f"Value of {env_variable}:\n{value}")
            raise ValueError(
                f"JSON object could not be decoded from {env_variable} env variable"
            )


def get_test_qc_param_from_cm_test_information(data, test_name, qc_param_name):  # noqa: C901
    """
    Function for reading CM_TEST_INFORMATION JSON variable for obtaining QC parameters. Structure of the JSON can be
    found within test/fixtures.py. Any change to the JSON structure would require also changing the function behavior

    :param data: CM_TEST_INFORMATION variable fetched via json.loads() from OS env variables
    :type data: dict
    :param test_name: Robot Framework test name for which QC params should be fetched
    :type test_name: str
    :param qc_param_name: QC parameter name from CM_TEST_INFORMATION. Available variables: id, qc_project, qc_domain
    :return: QC parameter value fetched from CM_TEST_INFORMATION JSON variable
    """
    for test in data["tests"]:
        for parameter in test["parameters"]:
            if parameter["name"] == "automation_options":
                automation_options = json.loads(parameter["value"])
                break
        else:
            continue
        if automation_options["test_case_name"] == test_name:
            for parameter in test["parameters"]:
                if parameter["name"] == qc_param_name:
                    return parameter["value"]
    return ""
